## 4. API Loading: `loadSessionDates` and `buildSessionDatesCoursesPayload`

### `loadSessionDates()` (lines 868–887)

```868:887:/home/admin/frontend/src/pages/CourseManagement.vue
const loadSessionDates = async () => {
  if (props.branchId == null || props.branchId === '') return;
  try {
    const token = await getToken();
    if (!token) return;
    const bodyCourses = buildSessionDatesCoursesPayload();
    const url = `/api/v1/student-classes/session-dates?branch_id=${props.branchId}`;
    const opts = {
      method: bodyCourses.length ? 'POST' : 'GET',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' }
    };
    if (bodyCourses.length) opts.body = JSON.stringify({ branch_id: Number(props.branchId), courses: bodyCourses });
    const res = await fetch(url, opts);
    if (!res.ok) return;
    const data = await res.json();
    sessionDatesByCourseId.value = (data && typeof data === 'object' && !Array.isArray(data)) ? data : {};
  } catch (e) {
    console.error('loadSessionDates', e);
  }
};
```

### `buildSessionDatesCoursesPayload()` (lines 641–687)

```641:666:/home/admin/frontend/src/pages/CourseManagement.vue
/** 從目前課程列表組出堂數制課程 payload，供 session-dates POST 使用（含請假/調課後日期） */
function buildSessionDatesCoursesPayload() {
  const list = courses.value;
  // ... groups by student_id|subject|teacher_id|start|end
  for (const rows of groups.values()) {
    const first = rows[0];
    if (first.payment_type !== 'session' || purchased <= 0) continue;
    // ...
    payload.push({
      id: r.id,
